P.entries["npc:sentinel-elissa-starbreeze"] = {n="Sentinel Elissa Starbreeze"}
P.entries["npc:sentinel-farsong"] = {n="Sentinel Farsong",s="Sentinel Farsong este o santinela elfa a noptii stationata la Silverwing Grove, in Ashenvale. Avand un rol esential de legatura pentru Silverwing Sentinels, ea coordoneaza informatiile si eforturile de lupta impotriva Warsong Outriders care inainteaza in Warsong Gulch.",h="Sentinel Farsong este o santinela elfa a noptii stationata la Silverwing Grove, in Ashenvale.",kw={"ashenvale","sentinel farsong","silverwing grove","silverwing sentinels","warsong gulch","warsong outriders"},ang={["faction:Alliance"]="Sentinel Farsong intruchipeaza mobilizarea din prima linie a Alliance in Ashenvale, trimitand voluntari direct in lupta impotriva Warsong Clan.",["race:NightElf"]="Ca aparatoare a padurilor sacre ale lui Elune, Farsong intruchipeaza hotararea kaldorei de a-i alunga pe toti cei care pangaresc crangurile stravechi."},sec={{t="Paznicul Silverwing Grove",b="Vegheand in Silverwing Grove, Sentinel Farsong este profund implicata in apararea granitei sudice din Ashenvale. In timp ce Warsong clan continua sa exploateze lemnul si sa patrunda tot mai adanc in teritoriile ancestrale ale elfilor noptii, ea mobilizeaza campionii Alliance pentru a-i ataca pe Warsong Outriders si se asigura ca rapoartele de pe teren ajung la conducerea Silverwing. Indatoririle ei se concentreaza asupra mobilizarii voluntarilor care sa opreasca expansiunea teritoriala a Horde si sa pastreze padurile sacre."}},faq={{q="Cine este Sentinel Farsong?",a="Sentinel Farsong este o santinela elf al noptii din randurile Silverwing Sentinels, in Ashenvale. Stationata la Silverwing Grove, langa intrarea in Warsong Gulch, ea recruteaza aventurieri ai Alliance si aduna informatii esentiale despre lupta.",al={"Farsong","povestea lui Sentinel Farsong","cine este Farsong"}},{q="Unde poate fi gasita?",a="Ea se afla la Silverwing Grove, in sud-estul Ashenvale, locul de unde Alliance isi coordoneaza eforturile militare neintrerupte din Warsong Gulch.",al={"locatia lui Sentinel Farsong","unde se afla farsong","harta lui farsong din Ashenvale"}},{q="De ce se lupta cu Warsong Outrider?",a="Warsong Outriders recolteaza lemn si pangaresc padurile sacre din Ashenvale. Farsong coordoneaza eforturile de aparare pentru a le opri operatiunile si a revendica teritoriul acaparat de Horde.",al={"de ce sa lupti cu Warsong Outriders","motivatia lui farsong","conflictul din Ashenvale"}}},fx={e9cb1820={q="De partea cui este Sentinel Farsong?",a="Sentinel Farsong slujeste Sentinels din Darnassus si Silverwing Sentinels, luptand de partea Alliance. Stationata la Silverwing Grove din Ashenvale, ea infrunta cu darzenie incursiunile Horde, strangand in jurul sau night elves si aliatii lor pentru a-si apara padurile stramosesti.",al={"factiunea lui farsong","pe cine slujeste farsong","Sentinel Farsong si alianta"}},a1fa54ea={q="Ce isi doreste Sentinel Farsong?",a="Sentinel Farsong urmareste indepartarea completa a Warsong Outrider si a invadatorilor din Horde din Ashenvale. Ea organizeaza rapoartele militare de pe front, aduna resurse si cheama campionii Alliance sa nimiceasca fortele invadatoare care ameninta padurea sacra.",al={"de ce are nevoie Farsong","scopul lui Farsong","misiunile lui Sentinel Farsong"}},ffcf1925={q="De ce se afla Sentinel Farsong aici?",a="Sentinel Farsong este stationata la Silverwing Grove, unde supravegheaza operatiunile de-a lungul granitelor nordice din Warsong Gulch. Ashenvale ramane sub asediul neintrerupt al Horde, iar ea joaca un rol esential de legatura, coordonand trupele si cercetarea impotriva operatiunilor forestiere care se apropie.",al={"de ce este Farsong in Ashenvale","Farsong Silverwing Grove","de ce este Sentinel Farsong aici"}},["31bb4497"]={q="De cine este legat Sentinel Farsong?",a="Sentinel Farsong este legata de Silverwing Sentinels si de armata mai larga a elfilor noptii, aflata sub comanda Darnassus. Ea actioneaza alaturi de aparatorii Alliance stationati in Silverwing Grove, mentinand legatura directa cu comandantii care coordoneaza apararea impotriva Warsong Clan.",al={"aliatii lui Farsong","legaturile lui Sentinel Farsong","cui ii raporteaza Farsong"}}},fp="16,251,28.463.0,24.238.0,23.142.0,42.197.0"}
P.entries["npc:sentinel-onaeya"] = {n="Sentinel Onaeya",s="Sentinel Onaeya este o gardiana night elf aflata la Maestra's Post, in nord-vestul Ashenvale, langa granita cu Darkshore. Avand sarcina de a tine piept pericolelor tot mai mari, ea aduna aventurieri Alliance capabili pentru a proteja padurea si a-si ajuta camarazii sentineli.",h="Sentinel Onaeya este o gardiana night elf aflata la Maestra's Post, in nord-vestul Ashenvale, langa granita...",kw={"Ashenvale","Darkshore","Maestra's Post","Night Elf","Onaeya","sentinela"},ang={["faction:Alliance"]="Onaeya coordoneaza sarcini defensive esentiale pentru calatorii Alliance care trec din salbaticia de pe coasta in padurile disputate din Ashenvale.",["faction:Horde"]="Ca sentinel devotata care apara Maestra's Post, Onaeya este o combatanta activa a inamicului, pazind caile de acces nordice spre Ashenvale.",["race:NightElf"]="Pentru elfii noptii care calatoresc spre sud din Darkshore, Onaeya reprezinta linia intai de aparare a padurii sacre din Ashenvale impotriva amenintarilor externe."},sec={{t="Un gardian la granita",b="Maestra's Post este un avanpost strategic de popas de-a lungul drumului din Darkshore spre desisul disputat al padurii Ashenvale. Sentinel Onaeya sta de straja in fata cabanei principale a asezarii, supraveghind atent calatorii si coordonand actiunile defensive. Intre fauna ostila, fortele corupatoare si tensiunile de la granita, sentinele precum Onaeya reprezinta prima linie de aparare a asezarilor night elf din regiune."},{t="Apararea avanpostului",b="Onaeya primeste vesti despre Sentinel Aynasha, atacata de furbolgi in timp ce transporta un mesaj important prin Darkshore. Ea ii rasplateste pe aventurierii care o protejeaza pe sentinelul otravita pana isi face efectul antidotul."}},faq={{q="Cine este Sentinel Onaeya?",a="Sentinel Onaeya este o santinela Night Elf stationata la Maestra's Post, in nord-vestul regiunii Ashenvale. Da misiuni si apara linia intai, indrumandu-i pe calatori sa ajute avanpostul.",al={"onaeya","sentinel onaeya","cine este onaeya"}},{q="Unde se afla Sentinel Onaeya?",a="Poate fi gasita stand chiar in fata cladirii principale din Maestra's Post, de-a lungul drumului din nordul Ashenvale, chiar sub granita cu Darkshore.",al={"locatia lui onaeya","unde este sentinel onaeya","gaseste-o pe onaeya"}},{q="De ce factiune apartine Sentinel Onaeya?",a="Este membra a Night Elf Sentinels si ii este loiala Alliance. Aventurierii Horde o vor gasi ostila de cum o vad.",al={"factiunea lui onaeya","onaeya face parte din alianta","onaeya este prietenoasa cu horda"}},{q="Ce legatura are Onaeya cu Sentinel Aynasha?",a="Sentinel Aynasha le cere aventurierilor sa se prezinte la Onaeya, la Maestra's Post, dupa ce o apara de furbolgii atacatori. Onaeya le rasplateste curajul si se bucura sa afle ca Aynasha a supravietuit.",al={"onaeya Aynasha","recompensa Sentinel Aynasha"}},{q="Ce fel de sarcini da Sentinel Onaeya?",a="Onaeya ii rasplateste pe aventurierii care o apara pe Sentinel Aynasha de furbolgii atacatori din Darkshore si ii duc vesti despre siguranta ei la Maestra's Post.",al={"misiuni onaeya","ce misiuni are onaeya"}},{q="De ce este important Maestra's Post pentru Sentinels?",a="Maestra's Post este un punct de control esential, care leaga rutele de aprovizionare din Darkshore de inima Ashenvale. Pastrarea lui impiedica incursiunile ostile sa intrerupa trecerea calatorilor night elf care se indreapta spre sud.",al={"de ce este importanta maestras post","importanta lui maestras post"}}},fx={e1ad0868={q="De ce este Sentinel Onaeya stationata la Maestra's Post?",a="Sentinel Onaeya sta de paza chiar in afara adapostului principal din Maestra's Post, in nord-vestul Ashenvale. Ca sentinel elf al noptii postat la granita, ea ajuta la apararea avanpostului impotriva amenintarilor din jur si primeste rapoarte de la calatorii care-i ajuta pe alti sentineli, precum Aynasha.",al={"de ce este Onaeya aici","locatia si motivul prezentei Sentinel Onaeya","de ce este Onaeya la Maestra's Post"}}},fp="15,274,23.435.0,16.215.0,23.187.0,33.154.0,44.122.0,44.186.0,45.140.0,49.197.0"}
P.entries["npc:sentinel-selarin"] = {n="Sentinel Selarin",s="Sentinel Selarin este o cercetasa elf al noptii trimisa in asezarea de coasta Auberdine. Ca emisar al aparatorilor din Ashenvale, ea cauta intariri pentru a opri pericolele tot mai mari care ameninta padurea straveche.",h="Sentinel Selarin este o cercetasa elf al noptii trimisa in asezarea de coasta Auberdine.",kw={"ashenvale","auberdine","darkshore","raene wolfrunner","selarin","sentinel selarin","santinele","terenthis"},ang={["faction:Alliance"]="Selarin este o veriga importanta pentru campionii Alliance care calatoresc spre sud, din Darkshore in tinuturile salbatice disputate din Ashenvale.",["race:NightElf"]="Ca membra a Sentinels, Selarin intruchipeaza vigilenta si unitatea necesare pentru apararea granitelor ancestrale ale kaldorei."},sec={{t="O cerere de intariri",b="Pe masura ce tensiunile si amenintarile intunecate se intetesc in Ashenvale, garnizoana de acolo a ajuns la capatul resurselor. La porunca lui Raene Wolfrunner, Sentinel Selarin a calatorit spre nord, de-a lungul drumului forestier, pana in Darkshore. Misiunea ei era simpla: sa-l gaseasca pe Terenthis in Auberdine si sa ceara ajutorul santinelelor si cercetasilor stationati pe coasta."},{t="Adunarea calatorilor",b="La sosirea in Auberdine, Selarin a descoperit ca Terenthis era coplesit de indatoririle locale si nu putea raspunde personal chemarii. In loc sa se intoarca cu mana goala, Selarin a hotarat sa ramana in oras si sa recruteze calatori capabili care treceau prin Darkshore. Ea ii indruma pe aventurierii incercati spre sud, catre Astranaar, indemnandu-i sa-si puna sabiile si vrajile in slujba fortelor impovarate ale lui Raene Wolfrunner."}},faq={{q="Cine este Sentinel Selarin?",a="Sentinel Selarin este o razboinica Night Elf din randul Sentinels. Slujeste drept curier si legatura, fiind trimisa din Ashenvale sa ceara ajutor asezarii Auberdine din Darkshore.",al={"povestea lui Selarin","cine este Selarin","Sentinel Selarin"}},{q="De ce a venit Selarin in Auberdine?",a="Raene Wolfrunner i-a ordonat sa-l gaseasca pe Terenthis in Auberdine si sa obtina intariri pentru a combate pericolele tot mai mari care ameninta salbaticia din Ashenvale.",al={"de ce se afla selarin in Darkshore","misiunea lui selarin","ce face selarin"}},{q="De ce nu a mers Terenthis cu ea in Ashenvale?",a="Terenthis era ocupat cu gestionarea unor chestiuni cruciale si cu investigarea amenintarilor din Darkshore. Prin urmare, Selarin a hotarat sa recruteze calatori independenti din Alliance pentru a porni spre sud.",al={"de ce nu ajuta terenthis","terenthis si selarin","terenthis este ocupat"}},{q="Unde le trimite ea pe aventurieri?",a="Ea ii indruma pe aventurieri spre sud, peste granita, in Ashenvale, pentru a-i raporta direct lui Raene Wolfrunner, la Astranaar.",al={"unde ma trimite selarin","destinatia misiunii lui selarin","dupa selarin"}}},fx={["5ef6a9e4"]={q="De partea cui este Sentinel Selarin?",a="Sentinel Selarin este un soldat loial al Sentinels Night Elf, slujind Alliance si raspunzand direct superiorilor din fortele de aparare ale Ashenvale, precum Raene Wolfrunner.",al={"factiunea lui Selarin","Sentinel Selarin face parte din Alliance","pe cine slujeste Selarin"}},bee3573a={q="Ce isi doreste Sentinel Selarin?",a="Selarin cauta intariri pentru problemele tot mai grave din Ashenvale. La inceput, a venit sa-l cheme pe Terenthis, dar, intelegand ca acesta are propriile indatoriri cruciale in Darkshore, isi propune sa adune aventurieri capabili care sa calatoreasca spre sud si sa o ajute pe Raene Wolfrunner.",al={"scopul lui selarin","de ce are nevoie selarin","ce incearca sa faca selarin"}},["8a8a2168"]={q="De cine este legat Sentinel Selarin?",a="Selarin slujeste sub comanda lui Raene Wolfrunner, care a trimis-o in misiune din Ashenvale. O cunoaste indeaproape si pe Terenthis din Auberdine si colaboreaza cu el pentru a obtine ajutor si a trimite recrutii promitatori pe linia frontului.",al={"pentru cine lucreaza Selarin","legaturile lui Selarin","Selarin si Raene Wolfrunner"}}},fp="16,230,25.381.0,22.397.0,24.182.0,34.162.0,46.196.0,32.119.0"}
P.entries["npc:sentinel-thenysil"] = {n="Sentinel Thenysil",s="Sentinel Tara Thenysil este o santinela elf al noptii stationata in Astranaar, in stravechea padure Ashenvale. Vegheaza asupra salbaticiei din imprejurimi, urmareste indeaproape operatiunile militare din regiune si coordoneaza cercetasii care supravegheaza tinuturile vecine. Atentia ei se indreapta indeosebi asupra trupelor aliate care inainteaza spre sud, in Stonetalon Mountains, un teritoriu disputat.",h="Sentinel Tara Thenysil este o santinela elf al noptii stationata in Astranaar, in stravechea padure Ashenvale.",kw={"Ashenvale","Astranaar","Kaela Shadowspear","sentinele","Stonetalon","Tara Thenysil","Thenysil","Tyrande Whisperwind"},ang={["faction:Alliance"]="Ca prima punte intre Ashenvale si Stonetalon Mountains, Thenysil le ofera aventurierilor Alliance prilejul de a castiga direct bunavointa conducerii din Darnassus.",["race:Gnome"]="Thenysil considera neobisnuita si ingrijoratoare trimiterea unui mag gnome din Alliance in Stonetalon, subliniind cat de ciudati li se par in continuare night elf aliatii lor marunti.",["race:NightElf"]="Thenysil reprezinta vigilenta neobosita a Sentinels, trudind fara incetare pentru a ocroti dumbravile sacre ale Kalimdorului si a-i mentine in siguranta pe agentii aliati de-a lungul granitelor."},sec={{t="Pazirea granitelor",b="Din postul sau din asezarea fortificata Astranaar, Sentinel Thenysil contribuie la apararea Ashenvale in fata ostilitatii tot mai mari. Teritoriile night elf din intreaga regiune sunt supuse unor incursiuni neintrerupte, ceea ce face ca legaturile dintre avanposturile indepartate sa fie vitale. In timp ce mare parte din garnizoana locala se ocupa direct de apararea drumului forestier, Thenysil trimite voluntari Alliance dincolo de granitele Ashenvale pentru a se asigura ca aliatii indepartati primesc sprijin."},{t="Legaturi cu Stonetalon",b="Thenysil are o relatie stransa, atat personala, cat si militara, cu Kaela Shadowspear, o agenta trimisa spre sud, in stancile din Stonetalon Mountains. Cand afla ca Kaela a fost trimisa alaturi de un mag gnom excentric, Thenysil vede in aceasta asociere neobisnuita un semn limpede ca se pregateste ceva grav in piscuri. Temandu-se de primejdiile cu care s-ar putea confrunta tovarasa ei, recruteaza aventurieri capabili sa calatoreasca spre sud, sa-i duca ajutor si sa raporteze despre desfasurarea misiunii."},{t="Audienta sub bolta copacilor",b="Cand cercetasii se intorc din Stonetalon cu vesti despre lovituri reusite impotriva Venture Company, Thenysil se asigura ca faptele lor nu trec neobservate. Intelegand ca respingerea exploatarii mecanizate din munti protejeaza salbaticia tuturor tinuturilor invecinate, ea le acorda eroilor de incredere o distinctie oficiala. In loc sa pastreze la Astranaar toate meritele pentru sine, ii trimite la Temple of the Moon din Darnassus, unde sunt primiti personal de High Priestess Tyrande Whisperwind."}},faq={{q="Unde poate fi gasit Sentinel Thenysil?",a="Sentinel Thenysil este stationata in Astranaar, principala fortareata a Night Elf, aflata de-a lungul drumului central din Ashenvale.",al={"locatia lui thenysil","unde se afla sentinel thenysil","thenysil astranaar"}},{q="De ce ii trimite Thenysil pe calatori in Stonetalon Mountains?",a="Prietena ei, Kaela Shadowspear, a fost trimisa in Stonetalon alaturi de un mag gnom. Considerand aceasta misiune neobisnuita un semn al unor primejdii iminente, Thenysil trimite aventurieri de incredere sa intareasca echipa Kaelei.",al={"de ce Stonetalon","misiunea lui Thenysil in Stonetalon","de ce misiunea On Guard in Stonetalon"}},{q="Cine este Kaela Shadowspear?",a="Kaela Shadowspear este o cercetasa elf al noptii si o prietena apropiata a lui Sentinel Thenysil. Este trimisa in Stonetalon Mountains pentru a investiga amenintarile la adresa tinutului.",al={"cine este Kaela","relatia lui Kaela Shadowspear","prietenul lui Thenysil"}},{q="Ce amenintari sunt infruntate in Stonetalon?",a="Pe langa incaierarile cu adversarii locali, Venture Company a infiintat operatiuni industriale invazive si distructive in Stonetalon Mountains, exploatand resursele si defrisand peisajul.",al={"amenintarea din Stonetalon","ce se intampla in Stonetalon","Venture Co si Stonetalon"}},{q="De ce trimite Thenysil aventurierii la Tyrande Whisperwind?",a="Dupa ce aventurierii o ajuta cu succes pe Kaela Shadowspear sa zadarniceasca planurile Venture Company din Stonetalon, Thenysil ii trimite la Darnassus, pentru ca High Priestess Tyrande Whisperwind sa le recunoasca personal serviciile aduse elfilor noptii.",al={"reception from tyrande","de ce sa o vezi pe tyrande","recomandarea lui thenysil catre darnassus"}},{q="Ce rol are Sentinel Thenysil in Astranaar?",a="Ea coordoneaza santinelele din Astranaar, ajutand la organizarea informatiilor regionale, supravegherea granitelor si trimiterea recrutilor de incredere din Alliance pentru a sprijini garnizoanele indepartate.",al={"rangul lui Thenysil","ce face Thenysil","indatoririle lui Sentinel Thenysil"}}},fx={cd8ae8e6={q="De partea cui este Sentinel Thenysil?",a="Sentinel Thenysil este devotata night elves si Alliance. Ca soldat activ in Sentinels cu baza in Astranaar, ea pazeste granitele Ashenvale si coordoneaza sprijinul pentru avanposturile si operatiunile night elf din tot Kalimdor.",al={"factiunea lui Sentinel Thenysil","pe cine slujeste Thenysil","Thenysil face parte din Alianta"}},ad790eb1={q="De ce se afla Sentinel Thenysil in Astranaar?",a="Astranaar este principalul centru Night Elf din Ashenvale si serveste drept post de comanda in prima linie pentru apararea padurii. Sentinel Thenysil este stationata acolo pentru a ajuta la supravegherea regiunii, a rutelor comerciale si la recrutarea calatorilor capabili, atunci cand tinuturile invecinate au nevoie de intariri urgente.",al={"de ce este thenysil in astranaar","avanpostul lui thenysil in ashenvale","de ce este sentinel thenysil aici"}}},fp="17,379,20.435.0,18.480.0,22.489.1,37.122.0,57.214.0,25.159.0,44.194.0,58.248.1,46.177.0"}
P.entries["npc:sentinel-tysha-moonblade"] = {n="Sentinel Tysha Moonblade"}
P.entries["npc:sentinel-velene-starstrike"] = {n="Sentinel Velene Starstrike",s="Sentinel Velene Starstrike este o paznica night elf stationata la Silverwind Refuge, in centrul Ashenvale. Insarcinata sa apere sanctuarul si apele dimprejur, infrunta amenintari supranaturale precum elementalii rataciti si vrajitorii ticalosi. Vigilenta ei contribuie la apararea padurii stravechi de influentele magice corupatoare.",h="Sentinel Velene Starstrike este o paznica night elf stationata la Silverwind Refuge, in centrul Ashenvale.",kw={"Ashenvale","bratari elementale","invocator de Mage","Mystral Lake","santinele","Silverwind Refuge","Starstrike","Velene"},ang={["class:Mage"]="Velene are putina rabdare cu cei care stapanesc vrajile, dar sunt iresponsabili, ale caror conjurari nesabuite agita elementalii locali si polueaza apele naturale.",["faction:Alliance"]="Silverwind Refuge ofera siguranta de-a lungul unui drum primejdios, iar Sentinel Velene coordoneaza eforturile locale de securizare a centrului Ashenvale.",["race:NightElf"]="Sentinel Velene intruchipeaza devotamentul neobosit al Sentinels, stand ca un bastion impotriva nechibzuintei magice pentru a pastra armonia naturala din Ashenvale."},sec={{t="Paznicul din Silverwind",b="Aflata langa apele limpezi ale Mystral Lake, Sentinel Velene Starstrike vegheaza din Silverwind Refuge. Ca multe santinele Night Elf raspandite prin Ashenvale, principala ei indatorire este sa pastreze echilibrul padurii si sa respinga amenintarile la adresa sanctuarelor elfice. Crangul tihnit este un popas esential pentru calatorii care strabat padurile centrale, ceea ce face ca prezenta ei sa fie vitala pentru siguranta neintrerupta a regiunii."},{t="Tulburari la Mystral Lake",b="Pacea din jurul Silverwind Refuge este fragila. Velene supravegheaza indeaproape Mystral Lake, unde spiritele elementale nestatornice si invocatorii de magie nechibzuiti tulbura ritmul firesc al salbaticiei. La porunca ei, campionii sunt trimisi sa inabuse razvratirea elementarilor apei si sa-i opreasca pe practicantii nepasatori care tulbura spiritele tinutului."}},faq={{q="Unde se afla Sentinel Velene Starstrike?",a="Sentinel Velene Starstrike este postata la Silverwind Refuge, un avanpost al Alliance aflat in centrul regiunii Ashenvale, aproape de tarmul sud-estic al Mystral Lake.",al={"locatia lui Velene Starstrike","unde se afla Velene","cel care da misiunea din Silverwind Refuge"}},{q="Ce sarcini ii atribuie Sentinel Velene?",a="Velene le cere aventurierilor sa se ocupe de spiritele tulburate si de practicantii din jurul Mystral Lake, trimitandu-i sa adune bratari de la elementalii nelinistiti si sa-i neutralizeze pe invocatorii renegati care agita apele.",al={"misiunile lui Velene Starstrike","ce misiuni ofera Velene"}},{q="Care este amenintarea de la Mystral Lake?",a="Apele din Mystral Lake au fost tulburate de elementali ai apei agresivi, agitati si exploatati de magi invocatori muritori care isi practica arta fara sa tina seama de echilibrul delicat al padurii.",al={"problema de la Mystral Lake","de ce sunt elementalii la Mystral Lake"}},{q="Are Velene vreo ruda in Kalimdor?",a="Ea poarta acelasi nume de familie, Starstrike, ca Layo Starstrike, un elf al noptii stationat departe, la sud, in tinuturile aride din Silithus, ceea ce sugereaza ca apartin aceleiasi descendente sau case.",al={"familia starstrike","ruda lui layo starstrike"}},{q="Ce este Silverwind Refuge?",a="Silverwind Refuge este un refugiu linistit al Night Elves, ascuns pe malurile Mystral Lake din Ashenvale. Este un adapost pasnic si un avanpost tactic pentru Sentinels si calatorii aliati care strabat tinuturile salbatice din inima padurii.",al={"ce este Silverwind Refuge","istoria lui Silverwind Refuge"}},{q="De ce le pasa Sentinels de activitatea elementala?",a="Night Elves privesc salbaticia drept un ecosistem sacru si viu. Elementalele violente sau corupte tulbura fauna locala si pangaresc cursurile naturale de apa, fortand Sentinels sa intervina si sa restabileasca echilibrul.",al={"de ce lupta Night Elves cu elementalii","sentinele si elementali"}}},fx={["8f53b9bb"]={q="Cine este Sentinel Velene Starstrike?",a="Sentinel Velene Starstrike este o gardiana Night Elf din randurile Sentinels, stationata la Silverwind Refuge, in Ashenvale. Asemenea surorilor ei de arme, este devotata apararii padurilor sacre din Kalimdor impotriva coruptiei si a intrusilor ostili, veghind cu vigilenta asupra tinuturilor invecinate, precum Mystral Lake.",al={"cine este Velene","povestea lui Velene Starstrike","cine este Sentinel Velene Starstrike"}},["2ad68975"]={q="De partea cui este Sentinel Velene Starstrike?",a="Sentinel Velene Starstrike este loiala Sentinels din randul elfilor noptii si sustine cu fermitate Alliance. Le ofera ajutor, indrumare si misiuni calatorilor care slujesc Alliance si vor sa ajute la apararea Ashenvale.",al={"factiunea lui velene starstrike","alianta santinelei velene","loialitatea lui velene starstrike"}},["33a0de05"]={q="De ce se afla aici Sentinel Velene Starstrike?",a="Velene este stationata la Silverwind Refuge pentru a supraveghea salbaticia si a coordona activitatea sentinelelor in centrul Ashenvale. Zona se confrunta cu pericole tot mai mari din partea faunei agresive, a elementarilor nestapaniti din jurul Mystral Lake si a incursiunilor straine care ameninta sfintenia padurilor.",al={"de ce este velene la silverwind refuge","scopul lui velene starstrike","de ce este velene starstrike in ashenvale"}},["9d94d468"]={q="Ce isi doreste Sentinel Velene Starstrike?",a="Velene cauta sa restabileasca armonia si siguranta in tinuturile salbatice din imprejurimi. Ea recruteaza campioni Alliance capabili sa cerceteze tulburarile elementale alarmante de la Mystral Lake, sa contracareze amenintarile magice si sa respinga orice forte ostile care se apropie de refugiu.",al={"ce vrea Velene","obiectivul lui Velene Starstrike","ce incearca sa faca Velene"}}},fp="26,346,22.440.0,28.360.0,44.156.0,39.211.0,35.212.0,45.180.0,26.232.0,51.213.0"}
P.entries["npc:serge-hinott"] = {n="Serge Hinott"}
P.entries["npc:shadow-priest-allister"] = {n="Shadow Priest Allister",s="Shadow Priest Allister este un preot Forsaken stationat la Sepulcher, in Silverpine Forest. Supraveghind activitatile de informatii si tactica din regiune, el coordoneaza operatiuni de monitorizare a vrajitorilor din Dalaran si de securizare a granitelor Lordaeronului pentru Dark Lady.",h="Shadow Priest Allister este un preot Forsaken stationat la Sepulcher, in Silverpine Forest.",kw={"Allister","Ambermill","Dalaran","Forsaken","holy bologna","Sepulcher","preot al Umbrei","Silverpine"},ang={["class:Priest"]="In calitate de autor al lucrarii 'Holy Bologna', Allister intruchipeaza deziluzia clerului Forsaken fata de Light.",["faction:Horde"]="Allister contribuie la securizarea Silverpine Forest, asigurandu-se ca aliatii Horde pot calatori in siguranta intre Tirisfal Glades si tinuturile din sud.",["race:Undead"]="Allister ilustreaza pragmatismul nemilos al Forsaken, intorcandu-i spatele vechilor dogme sacre pentru a-si proteja poporul de dusmanii vii."},sec={{t="Paznic la Sepulcher",b="Din Sepulcher, Shadow Priest Allister coordoneaza operatiunile de recunoastere ale celor Forsaken in tot Silverpine Forest. Din aceasta asezare centrala aflata intr-o cripta, urmareste amenintarile din apropiere, de la oameni renegati si incursiuni ale fiarelor pana la uneltirile arcane care se desfasoara in jurul Dalaran."},{t="Ochii atintiti asupra Ambermill si Dalaran",b="Principala grija a lui Allister sunt magii din Dalaran care au supravietuit, indeosebi cei care ocupa Ambermill si cerceteaza dincolo de granite. Nedorind sa-i lase pe Kirin Tor sa se inradacineze in tinuturile Forsaken, el trimite agenti sa intercepteze mesagerii din Dalaran, sa descifreze rune arcane si sa afle care sunt ambitiile pe termen lung ale vrajitorilor."},{t="Meditatii eretice",b="Dincolo de indatoririle sale de strateg de teren, Allister este un filosof cinic al intunericului. El este autorul lucrarii 'Holy Bologna: What the Light Won't Tell You' - un tratat usturator care critica doctrina sfanta traditionala. Textul exploreaza realitatile dure ale strigoilor si felul in care Holy Light ii abandoneaza pe cei respinsi de viata; cumva, lucrarea a ajuns sa circule pana departe, printre ruinele din Dire Maul, in Kalimdor."}},faq={{q="Cine este Shadow Priest Allister?",a="Este un preot al umbrelor Forsaken, stationat la Sepulcher, in Silverpine Forest, unde coordoneaza supravegherea si atacurile impotriva amenintarilor din apropiere, in special a fortelor din Dalaran.",al={"allister","shadow priest allister","cine este allister silverpine"}},{q="Unde il pot gasi pe Shadow Priest Allister?",a="Locuieste in Sepulcher, principala asezare a Forsaken, situata de-a lungul drumului principal care strabate Silverpine Forest.",al={"locatia lui allister","unde se afla shadow priest allister","gaseste-l pe allister"}},{q="De ce se concentreaza Allister asupra Dalaran si Ambermill?",a="Magii Kirin Tor stationati in Ambermill reprezinta o amenintare constanta pentru teritoriile Forsaken. Allister incearca sa le descifreze comunicarile, sa le afle intentiile si sa le tina influenta sub control.",al={"allister dalaran","de ce ataca ambermill","amenintarea dalaran la adresa silverpine"}},{q="Ce carte a scris Allister?",a="Allister a scris 'Holy Bologna: What the Light Won't Tell You', o critica ireverentioasa si muscatoare la adresa Holy Light, care a ajuns peste mare, pana la bibliotecile stravechi din Dire Maul.",al={"cartea lui Allister","Holy Bologna","ce nu-ti va spune Lumina"}},{q="Ce misiuni ofera Allister?",a="Ofera mai multe misiuni de strangere de informatii in Silverpine Forest, inclusiv Border Crossings, Maps and Runes, Ambermill Investigations si sarcini care ii vizeaza pe agentii din Dalaran.",al={"misiunile lui allister","misiunile preotului umbrelor din sepulcher"}},{q="De ce foloseste Allister magia Umbrei in locul Holy Light?",a="La fel ca multi preoti Forsaken care s-au simtit abandonati de Holy Light dupa moarte, Allister s-a indreptat spre umbre, gasind putere si hotarare intr-o disciplina care le imbratiseaza existenta de strigoi.",al={"de ce Priest al Umbrei","magia umbrelor a Forsaken, Allister"}}},fx={bfa3e4a4={q="De partea cui este Shadow Priest Allister?",a="Allister este absolut loial Forsaken si Dark Lady. Stationat in criptele din Sepulcher, isi pune in intregime artele intunecate si mintea calculata in slujba apararii Lordaeronului pentru strigoi si a neutralizarii oricarei amenintari regionale la adresa noului lor domeniu fragil.",al={"factiunea lui allister","pe cine slujeste shadow priest allister","este allister Forsaken"}},["9415cd7f"]={q="De ce se afla Shadow Priest Allister in Silverpine Forest?",a="Aflata la Sepulcher, Allister supravegheaza cu atentie enclavele ostile care zabovesc de-a lungul granitelor sudice. Intre vrajitorii supravietuitori din Dalaran, inradacinati in Ambermill, si magiile stranii care se agita in apropiere, rolul sau este sa trimita operativi Forsaken sa iscodeasca apararea dusmanului si sa-i afle adevaratele intentii.",al={"de ce este Allister la Sepulcher","scopul lui Allister in Silverpine","de ce se afla Shadow Priest Allister aici"}}},fp="22,262,24.282.0,29.332.0,17.407.0,30.172.0,40.123.0,49.198.0,29.191.0,32.183.0,66.194.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="Shadow Priest Sarvis",s="Shadow Priest Sarvis se afla in capela ruinata din Deathknell, fiind unul dintre principalii indrumatori ai noilor Forsaken treziti la viata. El le dezvaluie cadavrelor proaspat inviate cruda lor realitate si le indruma sa nimiceasca undead fara minte si sa adune informatii despre amenintarile locale. Sub steagul lui Lady Sylvanas, Sarvis trudeste neincetat pentru a-i transforma pe undead dezorientati in slujitori disciplinati ai Forsaken.",h="Shadow Priest Sarvis se afla in capela ruinata din Deathknell, fiind unul dintre principalii indrumatori ai...",kw={"deathknell","forsaken","novice elreth","sarvis","shadow priest sarvis","tirisfal glades"},ang={["class:Priest"]="Sarvis intruchipeaza imbratisarea magiei umbrelor de catre Forsaken, avand rolul unui mentor intunecat intr-o capela lipsita de Holy Light.",["race:Undead"]="Sarvis este una dintre primele voci pe care le auzi dupa ce te trezesti din mormant, pornindu-te pe calea slujirii Dark Lady."},sec={{t="Indrumatoarea celor proaspat treziti",b="In capela intunecata din Deathknell, Shadow Priest Sarvis ii asteapta pe cei care abia s-au tarat afara din mormant. Trezirea unui suflet Forsaken este zguduitoare si ingrozitoare, multi pierzandu-si numaidecat mintile, cuprinsi de furie oarba sau deznadejde. Sarvis le ofera celor proaspat ridicati un punct de sprijin si un rost. Le da recrutilor noi misiunea de a dobori cadavrele impleticite si lipsite de minte care ratacesc prin cimitir, apoi ii trimite sa apere granitele din Deathknell de Scourge, care se apropie."},{t="Asigurarea securitatii in Deathknell",b="Pe langa instruirea noilor recruti, Sarvis supravegheaza apararea locala esentiala impotriva amenintarilor care inca persista in Tirisfal Glades. El coordoneaza incercuirea fortelor Scourge care cerceteaza perimetrul din Deathknell. Indrumandu-i pe novice spre informatii vitale si incercari martiale, Sarvis se asigura ca orasul ramane un bastion fortificat al celor din Forsaken."}},faq={{q="Cine este Shadow Priest Sarvis?",a="Sarvis este un preot al umbrelor Forsaken, postat in Deathknell. Ii indruma pe mortii-vii abia treziti, dandu-le primele ordine si ajutand la apararea orasului impotriva Scourge.",al={"sarvis","cine este sarvis","preotul din deathknell"}},{q="Unde il pot gasi pe Shadow Priest Sarvis?",a="Se afla in biserica in ruina din centrul Deathknell, zona de inceput a Forsaken din Tirisfal Glades.",al={"locatia lui sarvis","unde se afla sarvis","gaseste-l pe sarvis"}},{q="De ce ii pune Sarvis pe jucatori sa ucida zombi fara minte?",a="Nu orice cadavru ridicat din mormant isi pastreaza vointa libera si mintea intreaga. Cei care cad prada nebuniei sunt considerati o amenintare pentru asezare si trebuie distrusi inainte sa-i puna in pericol pe mortii vii.",al={"de ce sa ucizi mindless ones","mindless ones"}}},fp="20,390,30.491.0,19.340.0,28.176.0,38.114.0,51.201.0"}
P.entries["npc:shael-dryn"] = {n="Shael'dryn",s="Shael'dryn este o dryad curioasa care locuieste langa Moonwell of Purity, la est de Iris Lake, in Ashenvale. Este un contact esential pentru cercetasii night elf care investigheaza coruptia padurii. Joaca un rol crucial, ajutand sentinelele din Astranaar cu relicve purificatoare, pentru a combate influentele demonice si malefice care se raspandesc prin salbaticie.",h="Shael'dryn este o dryad curioasa care locuieste langa Moonwell of Purity, la est de Iris Lake, in Ashenvale.",kw={"Ashenvale","Cenarius","purificare","dryada","Illiyana","Raene","Raynewood","Shael'dryn","Shaeldryn"},ang={["class:Druid"]="Druizii vor aprecia legatura ei fireasca cu spiritele din Kalimdor si intelegerea sa privind refacerea florei si faunei pervertite de puteri intunecate.",["faction:Alliance"]="Moonwell of Purity este un sanctuar in Ashenvale, unde Shael'dryn ajuta fortele Alliance-ului sa reziste coruptiei si incursiunilor ostile.",["race:NightElf"]="Pentru Kaldorei, Shael'dryn este o sora a padurii binevenita, ale carei legaturi cu natura si Cenarius o fac de neinlocuit in purificarea relicvelor padurii pangarite."},sec={{t="Paznicul Moonwell-ului",b="Stationat langa Moonwell of Purity, Shael'dryn vegheaza alaturi de santinelele night elf care pazesc caile de acces estice ale padurii. Cand coruptia se iveste printre vietuitoarele locale sau relicvele pangarite ameninta armonia tinutului, intelegerea profunda a naturii ii permite sa-i indrume pe aventurieri prin pasii necesari pentru restabilirea echilibrului spiritual."},{t="Purificarea padurii",b="Shael'dryn colaboreaza indeaproape cu Raene Wolfrunner in Astranaar. Cand sentinelele recupereaza artefacte pangarite, precum geme stralucitoare corupte si fragmentele pierdute din Dartol's Rod, Shael'dryn cunoaste ritualurile obscure, apele din moonwell si talismanele naturale necesare pentru a le purifica, transformand curiozitatile intunecate in instrumente puternice de curatare pentru Alliance."}},faq={{q="Cine este Shael'dryn?",a="Shael'dryn este o dryada care se afla langa Moonwell of Purity, in Ashenvale. Ea ii ajuta pe aventurierii Alliance cu cunostinte despre padure si magie a naturii, delectandu-se totodata cu predilectia ei pentru jocuri de cuvinte si glume.",al={"cine este ea","povestea lui Shael'dryn","identitatea lui Shael'dryn"}},{q="Unde o pot gasi pe Shael'dryn?",a="O poti gasi langa Moonwell of Purity, la est de Iris Lake, in Ashenvale.",al={"locatia lui Shael'dryn","unde este Shael'dryn","dryada din Raynewood"}},{q="Ce legatura are Shael'dryn cu Raene Wolfrunner?",a="Raene Wolfrunner ii trimite pe aventurieri la Shael'dryn, deoarece dryada are cunostintele spirituale necesare pentru a cerceta si curata nestematele si relicvele corupte gasite prin padure.",al={"Raene si Shaeldryn","purificarea lui Raene de catre dryada","de ce sa ma trimita la Shaeldryn"}},{q="Ce este neobisnuit la infatisarea lui Shael'dryn?",a="Shael'dryn si Illiyana, cealalta dryad, au o coloratie neobisnuita, care le deosebeste infatisarea de cea a majoritatii dryadelor intalnite in Kalimdor.",al={"model de driada","aspect unic","culoarea lui shaeldryn"}},{q="Este Shael'dryn prietenos cu Horde?",a="Nu. Aflata langa Moonwell of Purity si aliata strans cu Sentinels din Astranaar, Shael'dryn este ostila fata de membrii Horde.",al={"poate hoarda sa vorbeasca cu shaeldryn","reputatia hoardei","shaeldryn este doar pentru alianta"}}},fx={["70f31310"]={q="Ce vrea Shael'dryn?",a="Shael'dryn incearca sa protejeze si sa curete padurile din jurul Ashenvale. Ii ajuta pe aliati precum Raene Wolfrunner, indrumand calatorii sa cerceteze amenintarile, sa adune relicve stravechi ale padurii si sa restabileasca echilibrul in tinuturile corupte.",al={"scopul lui Shael'dryn","ce face Shael'dryn"}},["3c3b07cb"]={q="De ce se afla Shael'dryn la Moonwell of Purity?",a="Ca fiica a lui Cenarius, Shael'dryn vegheaza asupra estului regiunii Ashenvale din Moonwell of Purity, la est de Iris Lake. Din aceasta fantana lunara, ea supravegheaza coruptiile care se raspandesc prin padure si ii ajuta pe elfii noptii ce-si apara dumbravile sacre.",al={"de ce este Shael'dryn aici","de ce este Shael'dryn in Ashenvale","Shael'dryn si Raynewood"}}},fp="10,340,24.361.0,25.358.1,18.192.0,28.79.0,52.198.0,45.150.0,36.144.0"}
P.entries["npc:shanda"] = {n="Shanda"}
P.entries["npc:shandris-feathermoon"] = {n="Shandris Feathermoon",s="Shandris Feathermoon este generalul armatei Sentinel si, de zece mii de ani, mana dreapta a lui Tyrande Whisperwind. Acum comanda fortele militare ale elfilor noptii din intregul Kalimdor, de la Feathermoon Stronghold, de pe Sardor Isle, in largul coastei din Feralas.",h="Shandris Feathermoon este generalul armatei Sentinel si, de zece mii de ani, mana dreapta a lui Tyrande...",kw={"feathermoon","feralas","general","kaldorei","sardor isle","santinele","shandris","tyrande"},ang={["class:Hunter"]="Vanatorii si rangerii o venereaza pe Shandris drept una dintre cele mai bune tragatoare ale Sentinels, o general care i-a vegheat pe night elves timp de zece mii de ani.",["faction:Alliance"]="Pentru fortele Alliance care patrund in sudul Kalimdorului, General Feathermoon asigura o prezenta navala esentiala, conducere strategica si un sanctuar puternic fortificat pe Sardor Isle.",["faction:Horde"]="Horde il considera pe generalul Feathermoon un tactician militar periculos si viclean, a carui fortareata din largul coastei din Feralas ameninta expansiunea lor in regiune.",["race:NightElf"]="Pentru Kaldorei, General Feathermoon intruchipeaza culmea disciplinei si datoriei Sentinels, aparandu-si poporul inca de la inceputul lungii vegheri."},sec={{t="Mana dreapta a lui Tyrande",b="Shandris Feathermoon este una dintre cele mai vechi aparatoare ale elfilor noptii. De zece mii de ani ii slujeste alaturi lui Tyrande Whisperwind, fiind mana dreapta a marii preotese printre Sentinels, de-a lungul lungii vegheri care a urmat Sundering."},{t="Ascensiunea Sentinels",b="Dupa Great Sundering si intemeierea Sentinels, Shandris a devenit un comandant indispensabil in armata night elf."},{t="Bastionul din Feralas",b="Astazi, General Feathermoon este comandantul suprem de teren al armatei Sentinel. Aflata pe Sardor Isle, ea supravegheaza Feathermoon Stronghold, o fortareata elfa impunatoare, care vegheaza asupra salbaticiei primordiale din Feralas. Din acest avanpost insular, tine sub observatie amenintarile apropiate: gnolii salbatici, capcaunii Gordunni inca prezenti, satyr mistuiti de ura si puterea tot mai mare a Horde in sudul Kalimdor."}},faq={{q="Cine este Shandris Feathermoon?",a="Shandris Feathermoon este generalul Sentinels, forta militara permanenta a elfilor noptii. Fiind un elf al noptii stravechi, i-a fost mana dreapta lui Tyrande Whisperwind, Marea Preoteasa, timp de zece mii de ani si conduce Sentinels din Feathermoon Stronghold, in Feralas.",al={"cine este Shandris","povestea lui Shandris","cine este generalul Night Elf din Feralas"}},{q="Unde poate fi gasita Shandris Feathermoon?",a="Ea isi conduce trupele din Feathermoon Stronghold, aflata pe Sardor Isle, in largul coastei vestice a Feralas, in sudul Kalimdor.",al={"locatia lui Shandris","unde se afla Shandris Feathermoon","conducatorul Feathermoon Stronghold"}},{q="Ce relatie are Shandris cu Tyrande Whisperwind?",a="Shandris i-a fost mana dreapta lui Tyrande Whisperwind in randurile Sentinels timp de zece mii de ani. Tyrande ii conduce pe elfii noptii din Darnassus, in timp ce Shandris comanda armata Sentinels pe campul de lupta, din Feathermoon Stronghold.",al={"Shandris este fiica lui Tyrande","Tyrande si Shandris","copilul adoptiv al lui Tyrande"}},{q="A luptat Shandris impotriva Burning Legion?",a="Nicio lupta de-a ei impotriva Legiunii nu este consemnata in istoriile povestite aici. Se stie ca a slujit alaturi de Tyrande Whisperwind printre Sentinels timp de zece mii de ani, iar acum comanda armata Sentinels din Feathermoon Stronghold.",al={"war of the ancients shandris","a luptat shandris impotriva lui archimonde"}},{q="De ce este ea stationata in Feralas in loc de Teldrassil?",a="In calitate de general al Sentinels, Shandris trebuie sa conduca operatiunile militare din prima linie in tot Kalimdor. Feathermoon Stronghold serveste drept principal punct de concentrare si bastion al Alliance in padurile salbatice din sud, supraveghind ogrii ostili, satirii si activitatile Horde.",al={"de ce este Shandris in Feralas","de ce Feathermoon Stronghold"}}},fp="20,251,20.247.0,21.138.0,22.413.0,28.279.0,40.120.0,55.221.0,46.250.0,54.269.0"}
