P.entries["quest:10"] = {n="The Scrimshank Redemption",s="In Gadgetzan, Senior Surveyor Fizzledowser e ingrijorat: Junior Surveyor Scrimshank, unul dintre cei mai buni asistenti ai sai, trimis in Gaping Chasm, o zona desertica la sud-est de oras, a disparut. Ti se cere sa afli ce s-a intamplat cu Scrimshank sau, cel putin, sa gasesti echipamentul de masurare.",h="In Gadgetzan, Senior Surveyor Fizzledowser e ingrijorat: Junior Surveyor Scrimshank, unul dintre cei mai buni...",kw={"fizzledowser","gadgetzan","gaping chasm","scrimshank","cercetare","tanaris"},sec={{t="Un topograf disparut",b="Senior Surveyor Fizzledowser este ingrijorat. Junior Surveyor Scrimshank a intrat in Gaping Chasm si nu a mai fost vazut de atunci, iar ultimul raport de acolo vorbea despre si mai multe dintre acele insecte ciudate. Fizzledowser se intreaba daca insectele stapanesc acum doua regiuni vaste ale desertului. Ti se cere sa intri si sa-l cauti pe Scrimshank sau, daca nu-l gasesti, echipamentul de topografie, despre care Fizzledowser se teme ca ar putea fi tot ce-a mai ramas."},{t="Verdictul lui Fizzledowser",b="Scrimshank, dupa cum spune Fizzledowser, era un goblin de treaba, dar n-a supravietuit. Fizzledowser spera ca pierderea lui sa fi meritat, avand in vedere ce a reusit sa inregistreze echipamentul de cercetare. Insectele dau dovada de o inteligenta ingrijoratoare, iar cercetarile de pana acum indica faptul ca o a treia parte le controleaza, ceea ce prevesteste vremuri grele pentru Gadgetzan si intregul desert."}},faq={{q="Cine este Senior Surveyor Fizzledowser?",a="Fizzledowser este inspectorul principal din Gadgetzan, care cerceteaza insectele ciudate ale desertului si este superiorul lui Scrimshank.",al={"fizzledowser","cine ofera aceasta misiune","topograful fizzledowser"}},{q="Cine este Junior Surveyor Scrimshank?",a="Scrimshank era principalul asistent al lui Fizzledowser, trimis in desertul de la sud-est de Gadgetzan inainte sa dispara.",al={"scrimshank","cine este scrimshank","junior surveyor"}},{q="Unde se afla Gaping Chasm?",a="Este zona desertica de la sud-est de Gadgetzan pe care cartografii o numesc Gaping Chasm.",al={"locatia prapastiei uriase","unde este prapastia uriasa","locatia prapastiei"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza investigatia Noxious Lair.",al={"misiunea precedenta","conditie prealabila","ce misiune trebuie facuta mai intai"}}},fp="25,284,23.422.0,22.325.1,36.131.0,34.110.0,34.89.0,27.42.0"}
